ValidationRule.errorConditionFormula:
AND(
NOT(
$Setup.Metadata_Activation_Settings__c.Disable_VR__c && 
OR(
ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c), 
CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Account')
)
),
OR(
(BillingCountry!=null && LOWER(BillingCountry)  =='sweden' && 
NOT(REGEX( BillingPostalCode ,'^[0-9]{3} [0-9]{2}$'))
), 
(ShippingPostalCode != null && LOWER(ShippingCountry)  =='sweden' && 
NOT(REGEX( ShippingPostalCode, '^[0-9]{3} [0-9]{2}$')))
)
)
